from collections import deque
def transform(g):
    h,w=len(g),len(g[0])
    out=[r[:] for r in g]
    seen=[[False]*w for _ in range(h)]
    dq=deque()
    for i in range(h):
        for j in (0,w-1):
            if g[i][j]==0 and not seen[i][j]: seen[i][j]=True; dq.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if g[i][j]==0 and not seen[i][j]: seen[i][j]=True; dq.append((i,j))
    while dq:
        i,j=dq.popleft()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<h and 0<=nj<w and g[ni][nj]==0 and not seen[ni][nj]:
                seen[ni][nj]=True; dq.append((ni,nj))
    for i in range(h):
        for j in range(w):
            if g[i][j]==0 and not seen[i][j]: out[i][j]=8
    return out
